/* dcn41_modes.h - the mode table of the board this kext is built for (`make ASIC=...`, src/amd/asic_profile.h).
 *
 * Each board's table is GENERATED by `ASIC=<board> tools/dcn41/gen_modes.py` into dcn41_modes_<board>.{h,tsv}:
 *   navi44 (default, RX 9060 XT): every detailed timing of the monitors on this board, connectors from its VBIOS;
 *   navi48 (RX 9070 XT, Cobalt64's card): Cobalt64's original three-sink table (its EDID capture is not published,
 *          so that table is kept as generated upstream).
 */
#ifndef N4X_DCN41_MODES_SELECT_H
#define N4X_DCN41_MODES_SELECT_H
#if defined(N4X_ASIC_NAVI48)
#include "dcn41_modes_navi48.h"
#else
#include "dcn41_modes_navi44.h"
#endif
#endif
